/*
 * ADAM — القوانين والمقاسات الرسمية (الجزء ب): رياضات المضرب والرياضات القتالية
 * Official rules & dimensions per sport, part B (kind: rules, prefix rl_).
 *
 * Racket sports: tennis, table_tennis, squash, badminton, padel.
 * Combat sports: boxing, kickboxing, mma, judo, karate, taekwondo, wrestling, fencing.
 * Values come from the governing-body rulebook named in `source`.
 * Validate with:  node tools/check-hub.js rules library/sport-rules-b.js
 */

/* item: label + value, each { ar, en } */
const i = (lAr, lEn, vAr, vEn) => ({ label: { ar: lAr, en: lEn }, value: { ar: vAr, en: vEn } });
/* section */
const s = (id, ...items) => ({ id, items });
/* rule entry */
const r = (sport, source, ...sections) => ({ id: 'rl_' + sport, sport, source, sections });

